        > {
  $GraphVersionTableManager(_$AppDatabase db, GraphVersion table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $GraphVersionFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $GraphVersionOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $GraphVersionAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String> id = const Value.absent(),
                Value<String> graphId = const Value.absent(),
                Value<int> versionNumber = const Value.absent(),
                Value<String> snapshotJson = const Value.absent(),
                Value<String?> changeSummary = const Value.absent(),
                Value<int> createdAt = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => GraphVersionCompanion(
                id: id,
                graphId: graphId,
                versionNumber: versionNumber,
                snapshotJson: snapshotJson,
                changeSummary: changeSummary,
                createdAt: createdAt,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                required String id,
                required String graphId,
                required int versionNumber,
                required String snapshotJson,
                Value<String?> changeSummary = const Value.absent(),
                Value<int> createdAt = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => GraphVersionCompanion.insert(
                id: id,
                graphId: graphId,
                versionNumber: versionNumber,
                snapshotJson: snapshotJson,
                changeSummary: changeSummary,
                createdAt: createdAt,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) =>
                    (e.readTable(table), $GraphVersionReferences(db, table, e)),
              )
              .toList(),
          prefetchHooksCallback: ({graphId = false}) {
            return PrefetchHooks(
              db: db,
              explicitlyWatchedTables: [],
              addJoins:
                  <
                    T extends TableManagerState<
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic
                    >
                  >(state) {
                    if (graphId) {
                      state =
                          state.withJoin(
                                currentTable: table,
                                currentColumn: table.graphId,
                                referencedTable: $GraphVersionReferences
                                    ._graphIdTable(db),
                                referencedColumn: $GraphVersionReferences
                                    ._graphIdTable(db)
                                    .id,
                              )
                              as T;
                    }

                    return state;
                  },
              getPrefetchedDataCallback: (items) async {
                return [];
              },
            );
          },
        ),
      );
}

