class $GraphNodeTableManager
    extends
        RootTableManager<
          _$AppDatabase,
          GraphNode,
          GraphNodeData,
          $GraphNodeFilterComposer,
          $GraphNodeOrderingComposer,
          $GraphNodeAnnotationComposer,
          $GraphNodeCreateCompanionBuilder,
          $GraphNodeUpdateCompanionBuilder,
          (GraphNodeData, $GraphNodeReferences),
          GraphNodeData,
          PrefetchHooks Function({
            bool graphId,
            bool nodeSkillRefs,
            bool learningResourceRefs,
            bool noteNodeRefs,
            bool sessionNodeRefs,
            bool flashcardRefs,
            bool flashcardGroupRefs,
            bool multipleChoiceRefs,
            bool openEndedRefs,
            bool fsrsStateRefs,
            bool domainLogRefs,
          })
        > {
  $GraphNodeTableManager(_$AppDatabase db, GraphNode table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $GraphNodeFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $GraphNodeOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $GraphNodeAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String> id = const Value.absent(),
                Value<String> graphId = const Value.absent(),
                Value<String> type = const Value.absent(),
                Value<String> title = const Value.absent(),
                Value<String?> description = const Value.absent(),
                Value<double?> masteryScore = const Value.absent(),
                Value<bool> isSkipped = const Value.absent(),
                Value<double> positionX = const Value.absent(),
                Value<double> positionY = const Value.absent(),
                Value<int?> fsrsRating = const Value.absent(),
                Value<int> createdAt = const Value.absent(),
                Value<int> updatedAt = const Value.absent(),
                Value<bool> isFirstAccess = const Value.absent(),
                Value<bool> isAiGenerated = const Value.absent(),
                Value<bool> softDeleted = const Value.absent(),
                Value<int?> softDeletedAt = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => GraphNodeCompanion(
                id: id,
                graphId: graphId,
                type: type,
                title: title,
                description: description,
                masteryScore: masteryScore,
                isSkipped: isSkipped,
                positionX: positionX,
                positionY: positionY,
                fsrsRating: fsrsRating,
                createdAt: createdAt,
                updatedAt: updatedAt,
                isFirstAccess: isFirstAccess,
                isAiGenerated: isAiGenerated,
                softDeleted: softDeleted,
                softDeletedAt: softDeletedAt,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                required String id,
                required String graphId,
                required String type,
                required String title,
                Value<String?> description = const Value.absent(),
                Value<double?> masteryScore = const Value.absent(),
                Value<bool> isSkipped = const Value.absent(),
                required double positionX,
                required double positionY,
                Value<int?> fsrsRating = const Value.absent(),
                Value<int> createdAt = const Value.absent(),
                Value<int> updatedAt = const Value.absent(),
                Value<bool> isFirstAccess = const Value.absent(),
                Value<bool> isAiGenerated = const Value.absent(),
                Value<bool> softDeleted = const Value.absent(),
                Value<int?> softDeletedAt = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => GraphNodeCompanion.insert(
                id: id,
                graphId: graphId,
                type: type,
                title: title,
                description: description,
                masteryScore: masteryScore,
                isSkipped: isSkipped,
                positionX: positionX,
                positionY: positionY,
                fsrsRating: fsrsRating,
                createdAt: createdAt,
                updatedAt: updatedAt,
                isFirstAccess: isFirstAccess,
                isAiGenerated: isAiGenerated,
                softDeleted: softDeleted,
                softDeletedAt: softDeletedAt,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) => (e.readTable(table), $GraphNodeReferences(db, table, e)),
              )
              .toList(),
          prefetchHooksCallback:
              ({
                graphId = false,
                nodeSkillRefs = false,
                learningResourceRefs = false,
                noteNodeRefs = false,
                sessionNodeRefs = false,
                flashcardRefs = false,
                flashcardGroupRefs = false,
                multipleChoiceRefs = false,
                openEndedRefs = false,
                fsrsStateRefs = false,
                domainLogRefs = false,
              }) {
                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [
                    if (nodeSkillRefs) db.nodeSkill,
                    if (learningResourceRefs) db.learningResource,
                    if (noteNodeRefs) db.noteNode,
                    if (sessionNodeRefs) db.sessionNode,
                    if (flashcardRefs) db.flashcard,
                    if (flashcardGroupRefs) db.flashcardGroup,
                    if (multipleChoiceRefs) db.multipleChoice,
                    if (openEndedRefs) db.openEnded,
                    if (fsrsStateRefs) db.fsrsState,
                    if (domainLogRefs) db.domainLog,
                  ],
                  addJoins:
                      <
                        T extends TableManagerState<
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic
                        >
                      >(state) {
                        if (graphId) {
                          state =
                              state.withJoin(
                                    currentTable: table,
                                    currentColumn: table.graphId,
                                    referencedTable: $GraphNodeReferences
                                        ._graphIdTable(db),
                                    referencedColumn: $GraphNodeReferences
                                        ._graphIdTable(db)
                                        .id,
                                  )
                                  as T;
                        }

                        return state;
                      },
                  getPrefetchedDataCallback: (items) async {
                    return [
                      if (nodeSkillRefs)
                        await $_getPrefetchedData<
                          GraphNodeData,
                          GraphNode,
                          NodeSkillData
                        >(
                          currentTable: table,
                          referencedTable: $GraphNodeReferences
                              ._nodeSkillRefsTable(db),
                          managerFromTypedResult: (p0) =>
                              $GraphNodeReferences(db, table, p0).nodeSkillRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.nodeId == item.id,
                              ),
                          typedResults: items,
                        ),
                      if (learningResourceRefs)
                        await $_getPrefetchedData<
                          GraphNodeData,
                          GraphNode,
                          LearningResourceData
                        >(
                          currentTable: table,
                          referencedTable: $GraphNodeReferences
                              ._learningResourceRefsTable(db),
                          managerFromTypedResult: (p0) => $GraphNodeReferences(
                            db,
                            table,
                            p0,
                          ).learningResourceRefs,
                          referencedItemsForCurrentItem:
                              (item, referencedItems) => referencedItems.where(
                                (e) => e.nodeId == item.id,
                              ),
