class $GraphEdgeTableManager
    extends
        RootTableManager<
          _$AppDatabase,
          GraphEdge,
          GraphEdgeData,
          $GraphEdgeFilterComposer,
          $GraphEdgeOrderingComposer,
          $GraphEdgeAnnotationComposer,
          $GraphEdgeCreateCompanionBuilder,
          $GraphEdgeUpdateCompanionBuilder,
          (GraphEdgeData, $GraphEdgeReferences),
          GraphEdgeData,
          PrefetchHooks Function({
            bool graphId,
            bool sourceNodeId,
            bool targetNodeId,
          })
        > {
  $GraphEdgeTableManager(_$AppDatabase db, GraphEdge table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $GraphEdgeFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $GraphEdgeOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $GraphEdgeAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String> id = const Value.absent(),
                Value<String> graphId = const Value.absent(),
                Value<String> sourceNodeId = const Value.absent(),
                Value<String> targetNodeId = const Value.absent(),
                Value<String> type = const Value.absent(),
                Value<double?> weight = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => GraphEdgeCompanion(
                id: id,
                graphId: graphId,
                sourceNodeId: sourceNodeId,
                targetNodeId: targetNodeId,
                type: type,
                weight: weight,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                required String id,
                required String graphId,
                required String sourceNodeId,
                required String targetNodeId,
                required String type,
                Value<double?> weight = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => GraphEdgeCompanion.insert(
                id: id,
                graphId: graphId,
                sourceNodeId: sourceNodeId,
                targetNodeId: targetNodeId,
                type: type,
                weight: weight,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) => (e.readTable(table), $GraphEdgeReferences(db, table, e)),
              )
              .toList(),
          prefetchHooksCallback:
              ({graphId = false, sourceNodeId = false, targetNodeId = false}) {
                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [],
                  addJoins:
                      <
                        T extends TableManagerState<
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic
                        >
                      >(state) {
                        if (graphId) {
                          state =
                              state.withJoin(
                                    currentTable: table,
                                    currentColumn: table.graphId,
                                    referencedTable: $GraphEdgeReferences
                                        ._graphIdTable(db),
                                    referencedColumn: $GraphEdgeReferences
                                        ._graphIdTable(db)
                                        .id,
                                  )
                                  as T;
                        }
                        if (sourceNodeId) {
                          state =
                              state.withJoin(
                                    currentTable: table,
                                    currentColumn: table.sourceNodeId,
                                    referencedTable: $GraphEdgeReferences
                                        ._sourceNodeIdTable(db),
                                    referencedColumn: $GraphEdgeReferences
                                        ._sourceNodeIdTable(db)
                                        .id,
                                  )
                                  as T;
                        }
                        if (targetNodeId) {
                          state =
                              state.withJoin(
                                    currentTable: table,
                                    currentColumn: table.targetNodeId,
                                    referencedTable: $GraphEdgeReferences
                                        ._targetNodeIdTable(db),
                                    referencedColumn: $GraphEdgeReferences
                                        ._targetNodeIdTable(db)
                                        .id,
                                  )
                                  as T;
                        }

                        return state;
                      },
                  getPrefetchedDataCallback: (items) async {
                    return [];
                  },
                );
              },
        ),
      );
}

