              $NoteNodeFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $NoteNodeOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $NoteNodeAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String> id = const Value.absent(),
                Value<String> noteId = const Value.absent(),
                Value<String> nodeId = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => NoteNodeCompanion(
                id: id,
                noteId: noteId,
                nodeId: nodeId,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                required String id,
                required String noteId,
                required String nodeId,
                Value<int> rowid = const Value.absent(),
              }) => NoteNodeCompanion.insert(
                id: id,
                noteId: noteId,
                nodeId: nodeId,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) => (e.readTable(table), $NoteNodeReferences(db, table, e)),
              )
              .toList(),
          prefetchHooksCallback: ({noteId = false, nodeId = false}) {
            return PrefetchHooks(
              db: db,
              explicitlyWatchedTables: [],
              addJoins:
                  <
                    T extends TableManagerState<
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic
                    >
                  >(state) {
                    if (noteId) {
                      state =
                          state.withJoin(
                                currentTable: table,
                                currentColumn: table.noteId,
                                referencedTable: $NoteNodeReferences
                                    ._noteIdTable(db),
                                referencedColumn: $NoteNodeReferences
                                    ._noteIdTable(db)
                                    .id,
                              )
                              as T;
                    }
                    if (nodeId) {
                      state =
                          state.withJoin(
                                currentTable: table,
                                currentColumn: table.nodeId,
                                referencedTable: $NoteNodeReferences
                                    ._nodeIdTable(db),
                                referencedColumn: $NoteNodeReferences
                                    ._nodeIdTable(db)
                                    .id,
                              )
                              as T;
                    }

                    return state;
                  },
              getPrefetchedDataCallback: (items) async {
                return [];
              },
            );
          },
        ),
      );
}

