  static GraphNode _nodeIdTable(_$AppDatabase db) =>
      db.graphNode.createAlias('flashcard_group__node_id__graph_node__id');

  $GraphNodeProcessedTableManager get nodeId {
    final $_column = $_itemColumn<String>('node_id')!;

    final manager = $GraphNodeTableManager(
      $_db,
      $_db.graphNode,
    ).filter((f) => f.id.sqlEquals($_column));
    final item = $_typedResult.readTableOrNull(_nodeIdTable($_db));
    if (item == null) return manager;
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: [item]),
    );
  }

  static MultiTypedResultKey<
    FlashcardBelongsGroup,
    List<FlashcardBelongsGroupData>
  >
  _flashcardBelongsGroupRefsTable(_$AppDatabase db) =>
      MultiTypedResultKey.fromTable(
        db.flashcardBelongsGroup,
        aliasName:
            'flashcard_group__id__flashcard_belongs_group__flashcard_group_id',
      );

  $FlashcardBelongsGroupProcessedTableManager get flashcardBelongsGroupRefs {
    final manager =
        $FlashcardBelongsGroupTableManager(
          $_db,
          $_db.flashcardBelongsGroup,
        ).filter(
          (f) => f.flashcardGroupId.id.sqlEquals($_itemColumn<String>('id')!),
        );

    final cache = $_typedResult.readTableOrNull(
      _flashcardBelongsGroupRefsTable($_db),
    );
    return ProcessedTableManager(
      manager.$state.copyWith(prefetchedData: cache),
    );
  }
}

