class $GenericLogTableManager
    extends
        RootTableManager<
          _$AppDatabase,
          GenericLog,
          GenericLogData,
          $GenericLogFilterComposer,
          $GenericLogOrderingComposer,
          $GenericLogAnnotationComposer,
          $GenericLogCreateCompanionBuilder,
          $GenericLogUpdateCompanionBuilder,
          (GenericLogData, $GenericLogReferences),
          GenericLogData,
          PrefetchHooks Function({bool userId})
        > {
  $GenericLogTableManager(_$AppDatabase db, GenericLog table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $GenericLogFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $GenericLogOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $GenericLogAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<String> id = const Value.absent(),
                Value<String?> userId = const Value.absent(),
                Value<String> type = const Value.absent(),
                Value<String> payload = const Value.absent(),
                Value<int> createdAt = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => GenericLogCompanion(
                id: id,
                userId: userId,
                type: type,
                payload: payload,
                createdAt: createdAt,
                rowid: rowid,
              ),
          createCompanionCallback:
              ({
                required String id,
                Value<String?> userId = const Value.absent(),
                required String type,
                required String payload,
                Value<int> createdAt = const Value.absent(),
                Value<int> rowid = const Value.absent(),
              }) => GenericLogCompanion.insert(
                id: id,
                userId: userId,
                type: type,
                payload: payload,
                createdAt: createdAt,
                rowid: rowid,
              ),
          withReferenceMapper: (p0) => p0
              .map(
                (e) =>
                    (e.readTable(table), $GenericLogReferences(db, table, e)),
              )
              .toList(),
          prefetchHooksCallback: ({userId = false}) {
            return PrefetchHooks(
              db: db,
              explicitlyWatchedTables: [],
              addJoins:
                  <
                    T extends TableManagerState<
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic,
                      dynamic
                    >
                  >(state) {
                    if (userId) {
                      state =
                          state.withJoin(
                                currentTable: table,
                                currentColumn: table.userId,
                                referencedTable: $GenericLogReferences
                                    ._userIdTable(db),
                                referencedColumn: $GenericLogReferences
                                    ._userIdTable(db)
                                    .id,
                              )
                              as T;
                    }

                    return state;
                  },
              getPrefetchedDataCallback: (items) async {
                return [];
              },
            );
          },
        ),
      );
}

